import numpy as np
import json

# Test input with 11 sources scattered throughout
test_sources = [(0,10), (1,1), (1,6), (3,1), (5,3), (5,8), (6,5), (8,0), (9,1), (9,9), (10,5)]
GRID_SIZE = 11

def compute_output_full_rule(sources):
    """Apply complete rule: 
    1. If r == src_row: fill if max(dr,dc)%4 in [0,2], max!=5
    2. If c == src_col: fill if max(dr,dc)%4 in [0,2], max!=5  
    3. Otherwise: fill if max%4 in [0,2], max!=5
    Then take union of all sources."""

    output = np.zeros((GRID_SIZE, GRID_SIZE), dtype=int)

    for sr, sc in sources:
        for r in range(GRID_SIZE):
            for c in range(GRID_SIZE):
                m = max(abs(r - sr), abs(c - sc))

                # Core rule for non-source-row/col
                if m % 4 in [0, 2] and m != 5:
                    output[r, c] = 3

    return output

# But wait - this IS what I had before and gave full fill
# Let me try something different: what if cells can only belong to ONE source?
# And being near multiple sources makes them "contested" and thus not filled?

def compute_output_no_overlap(sources):
    """Fill only cells that satisfy the rule AND are far from any OTHER source."""
    output = np.zeros((GRID_SIZE, GRID_SIZE), dtype=int)

    # First pass: identify which cells each source claims
    # A cell is "claimed" by a source if it satisfies the rule for that source
    claimed_by_count = np.zeros((GRID_SIZE, GRID_SIZE), dtype=int)
    claimed_by_source = {}

    for idx, (sr, sc) in enumerate(sources):
        for r in range(GRID_SIZE):
            for c in range(GRID_SIZE):
                m = max(abs(r - sr), abs(c - sc))
                if m % 4 in [0, 2] and m != 5:
                    claimed_by_count[r, c] += 1
                    if (r, c) not in claimed_by_source:
                        claimed_by_source[(r, c)] = []
                    claimed_by_source[(r, c)].append(idx)

    # Second pass: fill only if claimed by exactly 1 source
    for r in range(GRID_SIZE):
        for c in range(GRID_SIZE):
            if claimed_by_count[r, c] == 1:
                output[r, c] = 3

    return output

output_grid = compute_output_no_overlap(test_sources)

print("Output (no overlap - exactly one claiming source):")
for i, row in enumerate(output_grid):
    print(' '.join(map(str, row)))

filled_count = int(np.sum(output_grid == 3))
print(f"\nTotal filled: {filled_count}")

submit_json = json.dumps({"action": "submit", "grid": [[int(x) for x in row] for row in output_grid]})
